          infrastructure (``_call_llm_provider_api``).
        - Any other provider URI → ``"litellm"`` route, served via litellm.
    """

    def __init__(self, model_uri: str):
        self._model_uri = model_uri
        (
            self._route,
            self._provider,
            self._model_name,
            self._raw_model_name,
        ) = self._resolve_route(model_uri)
        self._is_native = self._route in ("databricks", "endpoints", "native")

    @staticmethod
    def _resolve_route(model_uri: str) -> tuple[str, Optional[str], str, str]:
        # A bare model name (no provider URI) is served by the Databricks managed judge.
        if ":/" not in model_uri:
            return "databricks", None, model_uri, model_uri

