    """Create a DeepEval model adapter from a model URI.

    Returns a :class:`MlflowDeepEvalLLM` for the databricks, endpoints, and native provider
    routes, and falls back to litellm for unsupported providers.
    """
    client = ScorerLLMClient(model_uri)

    if client.is_native:
        return MlflowDeepEvalLLM(client)

    from deepeval.models import LiteLLMModel

    return LiteLLMModel(
        model=client.model_name,
        generation_kwargs={"drop_params": True},
    )
